function verifyCommit(sha, label) {
  const result = runGit(['cat-file', '-e', `${sha}^{commit}`]);
  if (!result.ok) {
    return { ok: false, error: `Cannot resolve ${label} commit ${sha}: ${result.error}` };
  }
  return { ok: true };
}

