    'OGZPrime protected path touched',
    `Author: ${details.author}`,
    `SHA: ${sha}`,
    `Subject: ${details.subject}`,
    'Files:',
    ...paths.map((filePath) => `- ${filePath}`),
  ].join('\n');
}

